#include<bits/stdc++.h>
#define MAXN 8010
using namespace std;
struct node{
    int val;
    int num;
    bool operator >(const node b) const{
        if(this->val!=b.val) return this->val > b.val;
        else return this->num > b.num;
    }
    bool operator <(const node b) const{
        if(this->val!=b.val) return this->val < b.val;
        else return this->num < b.num;
    }
};
node a[MAXN];
int n,q;
int type,x,v;



int order[MAXN];
void get_order(){
    for(int i=1;i<=n;i++){
        order[a[i].num]=i;
    }
}
void updata(int x,int v){
    a[order[x]].val=v;
    for(int i=order[x];i<n;i++){
        if(a[i]>a[i+1]){
            swap(a[i],a[i+1]);
        }
    }
    for(int i=order[x];i>1;i--){
        if(a[i]<a[i-1]){
            swap(a[i],a[i-1]);
        }
    }
    get_order();
}
int main(){


    scanf("%d%d",&n,&q);
    for(int i=1;i<=n;i++){
        scanf("%d",&a[i].val);
        a[i].num=i;
    }
    sort(a+1,a+n+1);
    get_order();
    while(q--){
        scanf("%d",&type);
        if(type==1){
            scanf("%d%d",&x,&v);
            updata(x,v);
        }else{
            scanf("%d",&x);
            printf("%d\n",order[x]);
        }
    }
    return 0;
}

